Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
$out = powercfg.exe /duplicatescheme 'e9a42b02-d5df-448d-aa00-03f14749eb61'

if ($out -match '([a-f0-9-]{36})') {
    powercfg.exe /setactive $Matches[1]

    powercfg.exe /change monitor-timeout-ac 0
    powercfg.exe /change monitor-timeout-dc 0
}

$Ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'

if (Test-Path $Ndu) {
    New-ItemProperty -Path $Ndu -Name 'Start' -PropertyType DWord -Value 4 -Force | Out-Null
}

Set-Service -Name 'DiagTrack' -StartupType Disabled -ErrorAction SilentlyContinue
Stop-Service -Name 'DiagTrack' -Force -ErrorAction SilentlyContinue

$Tasks = @(
    @{ TaskPath = '\Microsoft\Windows\Maintenance\'; TaskName = 'WinSAT' },
    @{ TaskPath = '\Microsoft\Windows\LanguageComponentsInstaller\'; TaskName = 'Installation' },
    @{ TaskPath = '\Microsoft\Windows\Customer Experience Improvement Program\'; TaskName = 'Consolidator' },
    @{ TaskPath = '\Microsoft\Windows\Customer Experience Improvement Program\'; TaskName = 'UsbCeip' },
    @{ TaskPath = '\Microsoft\Windows\Feedback\Siuf\'; TaskName = 'DmClient' },
    @{ TaskPath = '\Microsoft\Windows\Feedback\Siuf\'; TaskName = 'DmClientOnScenarioDownload' },
    @{ TaskPath = '\Microsoft\Windows\Application Experience\'; TaskName = 'Microsoft Compatibility Appraiser Exp' },
    @{ TaskPath = '\Microsoft\Windows\Application Experience\'; TaskName = 'StartupAppTask' }
)

foreach ($Task in $Tasks) {
