    'Running command: {0}' -f $(
      $script.ToString().Trim() -replace '\s+', ' '
    );
    $start = [datetime]::Now;
    & $script;
    'Completed in {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "$env:TEMP\UserOnce.log";

$scripts = @(
